func TestValidateJSONReportsInitialAndMaximumFleet(test *testing.T) {
	output, err := executeValidation(test, validationProfile(), "--json", "--max-cost", "100")
	if err != nil {
		test.Fatal(err)
	}
	var result validationOutput
	if err := json.Unmarshal([]byte(output), &result); err != nil {
		test.Fatal(err)
	}
	if !result.Valid || result.TargetRPS != 40_000 || result.InitialVMCount != 8 || result.MaxVMCount != 24 {
		test.Fatalf("unexpected JSON plan: %+v", result)
	}
	if result.EstimatedMaximumCost.MaxTrafficRPS != 120_000 || result.EstimatedMaximumCost.TotalUSD <= 0 {
		test.Fatalf("maximum fleet was not represented in the cost estimate: %+v", result.EstimatedMaximumCost)
	}
}

func TestValidateFailsClosedOnInvalidBudgets(test *testing.T) {
	for _, testCase := range []struct{ budget, message string }{
		{budget: "NaN", message: "finite"},
		{budget: "+Inf", message: "finite"},
		{budget: "-1", message: ">= 0"},
		{budget: "0.001", message: "exceeds"},
	} {
		test.Run(testCase.budget, func(test *testing.T) {
			output, err := executeValidation(test, validationProfile(), "--json", "--max-cost", testCase.budget)
			if err == nil || !strings.Contains(err.Error(), testCase.message) {
				test.Fatalf("got %v, want error containing %q", err, testCase.message)
			}
			if output != "" {
				test.Fatalf("invalid plan emitted success output: %s", output)
			}
		})
	}
}

func TestValidateRejectsManualFleetAboveCeiling(test *testing.T) {
	profile := validationProfile()
	profile.Fleet.InitialVMCount = 20
	_, err := executeValidation(test, profile, "--json")
	if err == nil || !strings.Contains(err.Error(), "initial fleet exceeds") {
		test.Fatalf("oversized manual fleet accepted: %v", err)
	}
}

func TestValidateRejectsPlaceholderBeforePlanning(test *testing.T) {
	profile := validationProfile()
	profile.Endpoints[0].URL = "https://example.com/health"
	_, err := executeValidation(test, profile, "--json")
	if err == nil || !strings.Contains(err.Error(), "documentation placeholders") {
		test.Fatalf("placeholder accepted: %v", err)
	}
}

func executeValidation(test *testing.T, profile *config.AttackProfile, flags ...string) (string, error) {
	test.Helper()
	contents, err := yaml.Marshal(profile)
	if err != nil {
		test.Fatal(err)
	}
	path := filepath.Join(test.TempDir(), "profile.yaml")
	if err := os.WriteFile(path, contents, 0600); err != nil {
		test.Fatal(err)
	}
	command := newValidateCmd()
	command.SilenceErrors = true
	command.SilenceUsage = true
	command.SetArgs(append([]string{path}, flags...))
	var output bytes.Buffer
	command.SetOut(&output)
	command.SetErr(&output)
	err = command.Execute()
	return output.String(), err
}

func validationProfile() *config.AttackProfile {
	return &config.AttackProfile{
		Version: 1,
		RunName: "unit-test",
		Target:  config.Target{RPS: 40_000, DurationSeconds: 60},
		Endpoints: []config.Endpoint{{
			ID: "health", Method: "GET", URL: "https://load-test.invalid/health",
			Weight: 1, Pattern: config.PatternKeepaliveBurst,
		}},
		Fleet: config.Fleet{
			Regions: []string{"eastus2", "westus2"}, VMSize: "Standard_F4s_v2",
			MaxVMCount: 24, UseSpot: true,
		},
		Lifecycle: config.Lifecycle{TTLMinutes: 10, CleanupOnInterrupt: true},
	}
}
